SELECT COUNT(DISTINCT BUS_ID) AS active_customers
FROM bank_dwh.D_CUST
WHERE IS_ACTV = TRUE AND IS_CURR = TRUE;

WITH current_customers AS (
  SELECT CUST_K FROM bank_dwh.D_CUST WHERE IS_CURR = true
), txns_2025 AS (
  SELECT DISTINCT CUST_K FROM bank_dwh.F_ACCT_TXN
  JOIN bank_dwh.D_DT ON F_ACCT_TXN.BUS_DT_K = D_DT.DT_K
  WHERE EXTRACT(YEAR FROM D_DT.CAL_DT) = 2025
)
SELECT COUNT(*) AS customers_no_txn_2025
FROM current_customers cc
WHERE NOT EXISTS (SELECT 1 FROM txns_2025 t WHERE t.CUST_K = cc.CUST_K);
